{
  "verdict": "request_changes",
  "summary": "Candidate updates state when version equals current version, violating the contract that requires strictly greater versions.",
  "findings": [
    {
      "finding_id": "SPEC-001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 4,
      "severity": "high",
      "description": "The function allows updates when the supplied version is equal to the current state version. The specification requires updates only when the supplied version is strictly greater than the current state version.",
      "evidence": "Calling advance(state={\"version\":2,\"value\":\"a\",\"writes\":0}, version=2, value=\"b\") returns True and updates state to {\"version\":2,\"value\":\"b\",\"writes\":1}. This violates the requirement that equal or older versions must return False and leave the entire state unchanged."
    }
  ]
}
